import{_ as l,C as i,o as c,c as p,a6 as o,j as t,a as s,E as a,w as u}from"./chunks/framework.BgIEWZ8W.js";const q=JSON.parse('{"title":"API Testing · Case File (Mental Model)","description":"Endpoint discovery, mass assignment, unused methods, and server-side parameter pollution explained like a detective investigation.","frontmatter":{"title":"API Testing · Case File (Mental Model)","description":"Endpoint discovery, mass assignment, unused methods, and server-side parameter pollution explained like a detective investigation."},"headers":[],"relativePath":"api-testing/index.md","filePath":"api-testing/index.md"}'),m={name:"api-testing/index.md"},g={class:"wd-case"},h={class:"wd-step wd-step--break"};function v(b,e,w,f,y,P){const r=i("Term"),n=i("LabGroup"),d=i("TopicComplete");return c(),p("div",null,[e[16]||(e[16]=o('<h1 id="api-testing-·-the-core-investigation" tabindex="-1">API Testing · The Core Investigation <a class="header-anchor" href="#api-testing-·-the-core-investigation" aria-label="Permalink to &quot;API Testing · The Core Investigation&quot;">​</a></h1><p class="wd-section-lede">Modern web applications are divided into two distinct halves: a sleek frontend user interface and a busy backstage API. Vulnerabilities emerge because backend APIs often trust incoming requests far more than the frontend does—accepting administrative fields, unadvertised HTTP methods, and parameter tricks that no browser button ever triggers.</p><div class="wd-callout"><p><strong>💡 Everyday Analogy: The Restaurant Kitchen Hatch.</strong> The dining room menu only lists soup and salad, and the waiter won&#39;t let you order a prime ribeye. But if you walk straight up to the kitchen service hatch and hand the cook an order ticket marked <em>&quot;1x Prime Ribeye, Price: $0.00&quot;</em>, a busy kitchen following automated recipes might prepare and serve it without question. An API is that kitchen hatch: if it doesn&#39;t verify authorization independently of the dining room menu, visitors can order whatever the backend knows how to cook.</p></div><h2 id="case-file-1-the-unchecked-profile-update" tabindex="-1">Case File #1: The Unchecked Profile Update <a class="header-anchor" href="#case-file-1-the-unchecked-profile-update" aria-label="Permalink to &quot;Case File #1: The Unchecked Profile Update&quot;">​</a></h2><p>Let&#39;s trace what happens when you update your email address in an account settings portal.</p>',5)),t("div",g,[e[14]||(e[14]=o('<div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>You type a new email into the profile form and click &quot;Save&quot;. Your browser sends an HTTP <code>PATCH /api/users/1337</code> request carrying a simple JSON body: <code>{&quot;email&quot;: &quot;detective@example.com&quot;}</code>.</p></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Server Does Behind the Scenes</span><p>The backend API framework parses the incoming JSON string and automatically binds its keys directly into the server&#39;s internal <code>User</code> database entity using framework auto-binding (such as Spring&#39;s model mapper or Node&#39;s <code>Object.assign</code>).</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Server Model Fields</span><span><span class="wd-code-input">Gold</span> = Client JSON Payload</span></div><span class="wd-code-dev">User.update({</span><span class="wd-code-input">&quot;email&quot;: &quot;detective@example.com&quot;</span><span class="wd-code-dev">})</span></div></div>',2)),t("div",h,[e[13]||(e[13]=t("span",{class:"wd-step__tag"},"💥 Step 3 · Where the Logic Breaks",-1)),t("p",null,[e[1]||(e[1]=s("The frontend HTML form only offered an email input, but the backend ",-1)),e[2]||(e[2]=t("code",null,"User",-1)),e[3]||(e[3]=s(" model also possesses attributes like ",-1)),e[4]||(e[4]=t("code",null,"role",-1)),e[5]||(e[5]=s(", ",-1)),e[6]||(e[6]=t("code",null,"isAdmin",-1)),e[7]||(e[7]=s(", and ",-1)),e[8]||(e[8]=t("code",null,"tier",-1)),e[9]||(e[9]=s(". Because the API binds whatever JSON keys are supplied without an allow-list, adding ",-1)),e[10]||(e[10]=t("code",null,'"role": "administrator"',-1)),e[11]||(e[11]=s(" to the raw request quietly elevates the user's account privileges—a classic ",-1)),a(r,{id:"mass-assignment"},{default:u(()=>[...e[0]||(e[0]=[s("mass assignment",-1)])]),_:1}),e[12]||(e[12]=s(" flaw.",-1))])]),e[15]||(e[15]=t("div",{class:"wd-step wd-step--fix"},[t("span",{class:"wd-step__tag"},"🛡️ Step 4 · How Developers Lock It Down"),t("p",null,"Developers define explicit Data Transfer Objects (DTOs) with strict allow-lists for each endpoint. Instead of binding raw input to the database model, the server only reads explicitly permitted fields and discards or rejects all extraneous properties.")],-1))]),e[17]||(e[17]=o('<h3 id="visual-comparison-frontend-form-vs-raw-api-binding" tabindex="-1">Visual Comparison: Frontend Form vs. Raw API Binding <a class="header-anchor" href="#visual-comparison-frontend-form-vs-raw-api-binding" aria-label="Permalink to &quot;Visual Comparison: Frontend Form vs. Raw API Binding&quot;">​</a></h3><div class="wd-compare"><div class="wd-compare__card wd-compare__card--expect"><span class="wd-compare__title">💭 What the Developer Expected</span><p>The developer assumed that because the web page form only presents inputs for <code>email</code> and <code>username</code>, the API endpoint would only ever receive those two properties from clients.</p></div><div class="wd-compare__card wd-compare__card--actual"><span class="wd-compare__title">💥 What Actually Happened</span><p>An investigator used an intercepting proxy to add <code>&quot;roleid&quot;: 2</code> to the JSON object. The server&#39;s ORM mapped every matching property directly to the database row, upgrading the account without verification.</p></div></div><h3 id="color-coded-breakdown-injecting-extra-properties" tabindex="-1">Color-Coded Breakdown: Injecting Extra Properties <a class="header-anchor" href="#color-coded-breakdown-injecting-extra-properties" aria-label="Permalink to &quot;Color-Coded Breakdown: Injecting Extra Properties&quot;">​</a></h3><p>Here is how an auto-binding API parses an expanded JSON request payload:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Standard User Input</span><span><span class="wd-code-input">Gold</span> = Injected Administrative Property</span><span><span class="wd-code-dead">Gray</span> = Unaltered Server Defaults</span></div><span class="wd-code-dev">{&quot;username&quot;: &quot;carlos&quot;, &quot;email&quot;: &quot;carlos@example.com&quot;, </span><span class="wd-code-input">&quot;role&quot;: &quot;admin&quot;</span><span class="wd-code-dev">}</span></div><hr><h2 id="the-4-stage-lifecycle-of-an-api-request" tabindex="-1">The 4-Stage Lifecycle of an API Request <a class="header-anchor" href="#the-4-stage-lifecycle-of-an-api-request" aria-label="Permalink to &quot;The 4-Stage Lifecycle of an API Request&quot;">​</a></h2><p>Understanding how an API processes requests helps pinpoint where authorization and parameter assumptions fail:</p><div class="wd-flow"><div class="wd-flow__node"><strong>1. Route Discovery</strong> Investigator locates endpoints via Swagger docs, JS bundles, or route fuzzing. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>2. Method Dispatch</strong> Router checks the HTTP verb (GET, POST, PUT, DELETE, PATCH, OPTIONS). </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>3. Parameter Binding</strong> Framework deserializes JSON body or URL parameters into model objects. (Mass assignment &amp; pollution happen here!) </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--safe"><strong>4. Service Execution</strong> App applies business logic and queries database or internal microservices. </div></div><hr><h2 id="the-detective-s-investigation-playbook" tabindex="-1">The Detective&#39;s Investigation Playbook <a class="header-anchor" href="#the-detective-s-investigation-playbook" aria-label="Permalink to &quot;The Detective&#39;s Investigation Playbook&quot;">​</a></h2><h3 id="_1-endpoint-discovery-hidden-blueprints" tabindex="-1">1. Endpoint Discovery &amp; Hidden Blueprints <a class="header-anchor" href="#_1-endpoint-discovery-hidden-blueprints" aria-label="Permalink to &quot;1. Endpoint Discovery &amp; Hidden Blueprints&quot;">​</a></h3><p>APIs rarely hide their documentation completely. Developers often leave interactive documentation frameworks active in production or embed API endpoints inside compiled JavaScript bundles:</p><ul><li><strong>Standard Documentation Paths:</strong> Check for <code>/api</code>, <code>/api/docs</code>, <code>/swagger</code>, <code>/swagger.json</code>, <code>/swagger-ui.html</code>, <code>/openapi.json</code>, and <code>/api/v1/</code>.</li><li><strong>HTTP Method Probing:</strong> If <code>GET /api/products/1</code> returns a product, test sending <code>OPTIONS /api/products/1</code> to see allowed verbs (<code>GET, POST, PUT, DELETE</code>), or try <code>DELETE /api/products/1</code>.</li><li><strong>Client-Side Source Bundles:</strong> Search downloaded JavaScript files for API path patterns like <code>&quot;/api/&quot;</code>, <code>&quot;baseURL&quot;</code>, and parameter names.</li></ul>',14)),a(n,{ids:"api-testing-lab-exploiting-api-endpoint-using-documentation, api-testing-lab-exploiting-unused-api-endpoint"}),e[18]||(e[18]=t("hr",null,null,-1)),e[19]||(e[19]=t("h3",{id:"_2-mass-assignment-auto-binding",tabindex:"-1"},[s("2. Mass Assignment (Auto-Binding) "),t("a",{class:"header-anchor",href:"#_2-mass-assignment-auto-binding","aria-label":'Permalink to "2. Mass Assignment (Auto-Binding)"'},"​")],-1)),e[20]||(e[20]=t("p",null,"In modern web frameworks, model-binding utilities make life easy for developers by automatically mapping request parameters directly onto internal database models. When an application accepts a user submission without an explicit allow-list, any internal property of the object can be overwritten.",-1)),a(n,{ids:"api-testing-lab-exploiting-mass-assignment-vulnerability"}),e[21]||(e[21]=o(`<details class="details custom-block"><summary>🔬 Under the Hood: Why Frameworks Auto-Bind by Default</summary><p>Different application frameworks implement auto-binding through reflection:</p><ul><li><strong>Spring (Java):</strong> <code>@ModelAttribute</code> and Jackson object mapper inspect setter methods and invoke any setter that matches an incoming JSON field.</li><li><strong>Ruby on Rails:</strong> Calling <code>User.new(params[:user])</code> without using <code>params.require(:user).permit(...)</code> (&quot;strong parameters&quot;) binds every submitted key.</li><li><strong>Django REST Framework (Python):</strong> Serializers configured with <code>fields = &quot;__all__&quot;</code> expose all model fields for update unless explicitly set to <code>read_only_fields</code>.</li><li><strong>Node.js / Express:</strong> Code using <code>Object.assign(user, req.body)</code> or <code>user.set(req.body)</code> copies every property into the user model.</li></ul><p>The secure architectural pattern is <strong>Input Allow-Listing</strong>: use dedicated request DTOs that only contain fields meant to be modified by the current caller.</p></details><hr><h3 id="_3-server-side-parameter-pollution-sspp" tabindex="-1">3. Server-Side Parameter Pollution (SSPP) <a class="header-anchor" href="#_3-server-side-parameter-pollution-sspp" aria-label="Permalink to &quot;3. Server-Side Parameter Pollution (SSPP)&quot;">​</a></h3><p>When a front-facing web server receives a request and constructs a second, internal request to a backend microservice, delimiters in user input can change how the backend interprets the message:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Front-end request:   GET /user/lookup?username=carlos</span></span>
<span class="line"><span>Internal backend call: GET http://internal-service/user?username=carlos&amp;role=standard</span></span>
<span class="line"><span>                                                                 ▲</span></span>
<span class="line"><span>User input injected here ────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>If the user submits <code>username=carlos%26role%3Dadmin</code>, the internal URL becomes: <code>http://internal-service/user?username=carlos&amp;role=admin&amp;role=standard</code></p><p>Depending on which parameter the internal server prioritizes, the injected administrative role can override the server&#39;s default!</p>`,7)),a(n,{ids:"api-testing-lab-exploiting-server-side-parameter-pollution-in-query-string, api-testing-lab-exploiting-server-side-parameter-pollution-in-rest-url"}),e[22]||(e[22]=o('<details class="details custom-block"><summary>⚙️ Engine Variations: How Parsers Handle Duplicate Parameters</summary><p>When a query string contains duplicate parameters (e.g., <code>?role=user&amp;role=admin</code>), different backend technologies choose different values:</p><table tabindex="0"><thead><tr><th>Framework / Engine</th><th>Duplicate Parameter Behavior</th><th>Example: <code>?user=alice&amp;user=bob</code></th></tr></thead><tbody><tr><td><strong>PHP / Apache</strong></td><td>Uses the <strong>last</strong> occurrence</td><td>Value is <code>&quot;bob&quot;</code></td></tr><tr><td><strong>Node.js / Express (<code>qs</code>)</strong></td><td>Creates an <strong>array</strong></td><td>Value is <code>[&quot;alice&quot;, &quot;bob&quot;]</code></td></tr><tr><td><strong>ASP.NET</strong></td><td>Joins with <strong>comma</strong></td><td>Value is <code>&quot;alice,bob&quot;</code></td></tr><tr><td><strong>Go (<code>net/url</code>)</strong></td><td><code>URL.Query().Get()</code> takes the <strong>first</strong></td><td>Value is <code>&quot;alice&quot;</code></td></tr><tr><td><strong>Python (<code>Flask</code>/<code>urllib</code>)</strong></td><td><code>request.args.get()</code> takes the <strong>first</strong></td><td>Value is <code>&quot;alice&quot;</code></td></tr></tbody></table><p>Parameter pollution exploits the disagreement between what a frontend security check validates (e.g., the first parameter) and what the backend execution engine consumes (e.g., the last parameter).</p></details><hr><h2 id="the-detective-s-api-testing-routine" tabindex="-1">The Detective&#39;s API Testing Routine <a class="header-anchor" href="#the-detective-s-api-testing-routine" aria-label="Permalink to &quot;The Detective&#39;s API Testing Routine&quot;">​</a></h2><p>When auditing an unfamiliar API surface:</p><ol><li><strong>Map the Surface:</strong> Review API documentation files (<code>/swagger</code>, <code>/openapi.json</code>) and extract API route strings from client-side <code>.js</code> bundles.</li><li><strong>Probe HTTP Verbs:</strong> Try alternate HTTP verbs (<code>PUT</code>, <code>DELETE</code>, <code>PATCH</code>, <code>OPTIONS</code>) on read-only endpoints.</li><li><strong>Inspect Payloads for Auto-Binding:</strong> On <code>POST</code> and <code>PATCH</code> requests, inspect the response body. If the response displays fields not present in the request (e.g., <code>role</code>, <code>status</code>, <code>balance</code>), add those properties to your submission.</li><li><strong>Test Parameter Pollution:</strong> Insert URL-encoded delimiters (<code>%26</code>, <code>%23</code>, <code>%3F</code>, <code>../</code>) into query parameters and REST path segments to determine if internal requests can be reshaped.</li><li><strong>Vary Content-Type:</strong> Change <code>application/x-www-form-urlencoded</code> to <code>application/json</code> or <code>application/xml</code> to test whether alternate backend parsers are exposed.</li></ol><hr><h2 id="how-developers-lock-it-down-permanently" tabindex="-1">How Developers Lock It Down Permanently <a class="header-anchor" href="#how-developers-lock-it-down-permanently" aria-label="Permalink to &quot;How Developers Lock It Down Permanently&quot;">​</a></h2><div class="wd-callout wd-callout--warn"><p><strong>🛡️ The Golden Rules of Secure API Design:</strong></p><ul><li><strong>Use Strict Request DTOs:</strong> Never bind incoming request bodies directly into database models. Use explicit Data Transfer Objects that only declare fields the caller is authorized to modify.</li><li><strong>Disable Unused HTTP Verbs:</strong> Explicitly configure routers to reject unneeded methods with <code>405 Method Not Allowed</code> rather than leaving default CRUD handlers open.</li><li><strong>Build Safe Internal URLs:</strong> Never concatenate user input into internal API URLs using strings. Use URL builder libraries that automatically encode parameters properly.</li><li><strong>Protect API Documentation:</strong> Restrict interactive API consoles (Swagger UI, GraphiQL) in production to authenticated internal networks.</li><li><strong>Validate Schema Rigorously:</strong> Reject any request carrying unknown properties with <code>400 Bad Request</code> rather than silently dropping or passing them.</li></ul></div>',8)),a(d,{"topic-id":"api-testing",label:"Mark API testing complete"})])}const _=l(m,[["render",v]]);export{q as __pageData,_ as default};
